def apply(asset):
    have = {r["id"] for r in asset["provenance"]["references"]}
    asset["provenance"]["references"] += [r for r in REFERENCES if r["id"] not in have]
    asset["provenance"]["notes"] = NOTES
    for region in asset["thermal"]["regions"]:
        if region["id"] in AREAS:
            region["areaM2"] = AREAS[region["id"]]
    asset["thermal"]["assumptions"] = [CASTOR_ASSUMPTION if "castors are summarised" in a["en"] else a for a in asset["thermal"]["assumptions"]]
    for scale, texts in DECISIONS.items():
        target = asset["representations"][scale]["decisions"]
        for key, (en, de) in texts.items():
            target[key] = {"en": en + (SWIVEL["en"] if key == "silhouette" else ""), "de": de + (SWIVEL["de"] if key == "silhouette" else "")}
